package com.rekluzlabs.makokolorize.ui.componentsimport android.Manifestimport android.net.Uriimport android.os.Buildimport androidx.activity.compose.rememberLauncherForActivityResultimport androidx.activity.result.contract.ActivityResultContractsimport androidx.compose.foundation.clickableimport androidx.compose.foundation.layout.Arrangementimport androidx.compose.foundation.layout.Boximport androidx.compose.foundation.layout.Columnimport androidx.compose.foundation.layout.PaddingValuesimport androidx.compose.foundation.layout.aspectRatioimport androidx.compose.foundation.layout.fillMaxSizeimport androidx.compose.foundation.layout.paddingimport androidx.compose.foundation.lazy.grid.GridCellsimport androidx.compose.foundation.lazy.grid.LazyVerticalGridimport androidx.compose.foundation.lazy.grid.itemsimport androidx.compose.foundation.shape.RoundedCornerShapeimport androidx.compose.material3.Buttonimport androidx.compose.material3.CircularProgressIndicatorimport androidx.compose.material3.Textimport androidx.compose.runtime.Composableimport androidx.compose.runtime.LaunchedEffectimport androidx.compose.runtime.getValueimport androidx.compose.runtime.mutableStateOfimport androidx.compose.runtime.rememberimport androidx.compose.runtime.setValueimport androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.draw.clipimport androidx.compose.ui.layout.ContentScaleimport androidx.compose.ui.platform.LocalContextimport androidx.compose.ui.text.style.TextAlignimport androidx.compose.ui.unit.dpimport coil.compose.AsyncImageimport com.rekluzlabs.makokolorize.data.image.ImageRepository@Composablefun CustomGallery(    onImageSelected: (Uri) -> Unit,    modifier: Modifier = Modifier,) {    val context = LocalContext.current    var images by remember { mutableStateOf<List<Uri>>(emptyList()) }    var isLoading by remember { mutableStateOf(value = true) }    var hasPermission by remember { mutableStateOf(value = false) }    val permissionToRequest = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {        Manifest.permission.READ_MEDIA_IMAGES    } else {        Manifest.permission.READ_EXTERNAL_STORAGE    }    val launcher = rememberLauncherForActivityResult(        ActivityResultContracts.RequestPermission(),    ) { isGranted ->        hasPermission = isGranted    }    LaunchedEffect(Unit) {        // Simple check - in a real app you'd check ContextCompat.checkSelfPermission        // But for this example we'll trigger the launcher if not granted        launcher.launch(permissionToRequest)    }    LaunchedEffect(hasPermission) {        if (hasPermission) {            isLoading = true            val repository = ImageRepository(context)            repository.fetchLocalImages().onSuccess {                images = it                isLoading = false            }.onFailure {                isLoading = false            }        }    }    if (!hasPermission) {        Box(modifier = modifier.fillMaxSize(), contentAlignment = Alignment.Center) {            Column(horizontalAlignment = Alignment.CenterHorizontally) {                Text(                    "Permission required to access gallery",                    modifier = Modifier.padding(16.dp),                    textAlign = TextAlign.Center                )                Button(onClick = { launcher.launch(permissionToRequest) }) {                    Text("Grant Permission")                }            }        }    } else if (isLoading) {        Box(modifier = modifier.fillMaxSize(), contentAlignment = Alignment.Center) {            CircularProgressIndicator()        }    } else if (images.isEmpty()) {        Box(modifier = modifier.fillMaxSize(), contentAlignment = Alignment.Center) {            Text("No images found on device")        }    } else {        LazyVerticalGrid(            columns = GridCells.Fixed(3),            modifier = modifier.fillMaxSize(),            contentPadding = PaddingValues(4.dp),            horizontalArrangement = Arrangement.spacedBy(4.dp),            verticalArrangement = Arrangement.spacedBy(4.dp)        ) {            items(images) { uri ->                GalleryItem(uri = uri) { onImageSelected(uri) }            }        }    }}@Composablefun GalleryItem(    uri: Uri,    onClick: () -> Unit) {    AsyncImage(        model = uri,        contentDescription = null,        modifier = Modifier            .aspectRatio(1f)            .clip(RoundedCornerShape(8.dp))            .clickable(onClick = onClick),        contentScale = ContentScale.Crop    )}